/* Supplemental review guidance, never counted as benchmark controls or compliance. */
(()=>{'use strict';
const entries={
 '3':[['Logların saxlanma və mərkəzə ötürülmə tələblərini müəyyən edin.','Define log retention and central forwarding requirements.'],['Event log giriş icazələrini nəzərdən keçirin; audit qaydaları üçün 17-ci bölməyə baxın.','Review event-log access permissions; see section 17 for audit controls.'],'17'],
 '4':[['Lokal Administrators və digər imtiyazlı qrupların üzvlərini inventarlaşdırın.','Inventory local Administrators and other privileged group memberships.'],['Təsdiqlənmiş üzvlük siyahısı hazırlayın; tətbiqdən əvvəl bərpa hesabını qoruyun.','Define approved membership and preserve recovery access before enforcement.'],'2'],
 '6':[['Həssas registry açarlarının ACL və inheritance vəziyyətini nəzərdən keçirin.','Review ACLs and inheritance on sensitive registry keys.'],['Registry dəyərlərini dəyişən control-lar 18-ci və digər siyasət bölmələrindədir.','Controls configuring registry values appear in section 18 and other policy sections.'],'18'],
 '7':[['Həssas qovluqların NTFS/share icazələrini və inheritance vəziyyətini nəzərdən keçirin.','Review NTFS/share permissions and inheritance for sensitive directories.'],['İcazə dəyişikliyindən əvvəl ACL ehtiyatını və tətbiq hesablarının girişini yoxlayın.','Before changing permissions, review ACL backups and application-account access.'],'2'],
 '8':[['802.1X/EAP uyğunluğunu, sertifikatları və switch/RADIUS tələblərini inventarlaşdırın.','Inventory 802.1X/EAP support, certificates and switch/RADIUS requirements.'],['Şəbəkə giriş siyasətini ayrıca pilotda sınaqdan keçirin; bərpa bağlantısını saxlayın.','Pilot network-access policy separately and retain recovery connectivity.'],'9'],
 '10':[['Domain, Private və Public şəbəkə profillərinin düzgün seçildiyini yoxlayın.','Review correct Domain, Private and Public network-profile classification.'],['Naməlum şəbəkələr və profil dəyişmə icazələrini təşkilat tələbinə görə nəzərdən keçirin.','Review unidentified networks and profile-change permissions against organizational requirements.'],'9'],
 '11':[['Təsdiqlənmiş Wi-Fi profillərini və autentifikasiya/sertifikat tələblərini müəyyən edin.','Define approved Wi-Fi profiles and authentication/certificate requirements.'],['Siyasəti məhdud cihazlarda test edin; şəbəkə bağlantısının kəsilməsini nəzərə alın.','Test on limited devices and account for connectivity loss.'],'9'],
 '12':[['Trusted Root, sertifikat müddətləri və revocation tələblərini nəzərdən keçirin.','Review trusted roots, certificate expiration and revocation requirements.'],['Auto-enrollment tətbiq ediləcəksə CA/template icazələrini ayrıca qiymətləndirin.','Assess CA/template permissions separately before auto-enrollment.'],'2'],
 '13':[['Mövcud software restriction qaydalarını və tətbiq inventarını nəzərdən keçirin.','Review existing software restriction rules and application inventory.'],['Yeni tətbiq nəzarəti üçün App Control/AppLocker uyğunluğunu qiymətləndirin; əvvəl audit/pilot edin.','Assess App Control/AppLocker compatibility for new application control; start with audit/pilot.'],'15'],
 '14':[['Bu legacy GPMC bölməsinin mühitinizdə istifadə olunub-olunmadığını müəyyən edin.','Determine whether this legacy GPMC category is used in your environment.'],['Şəbəkə girişini təşkilatın dəstəklənən NAC/802.1X həlli ilə ayrıca qiymətləndirin.','Assess network admission through the organization’s supported NAC/802.1X solution.'],'8'],
 '15':[['Tətbiq inventarı və istisnaları hazırlayın; AppLocker/App Control uyğunluğunu qiymətləndirin.','Inventory applications and exceptions; assess AppLocker/App Control compatibility.'],['Əvvəl audit/pilot rejimini seçin, sonra ayrıca təsdiqlə enforcement edin.','Start with audit/pilot and approve enforcement separately.'],'18'],
 '16':[['IPsec autentifikasiyası, sertifikat/Kerberos və trafik asılılıqlarını nəzərdən keçirin.','Review IPsec authentication, certificate/Kerberos and traffic dependencies.'],['Connection Security Rules siyasətini pilot edin; idarəetmə bağlantısını qoruyun.','Pilot Connection Security Rules and preserve management connectivity.'],'9']
};
function render(state,domain,esc,say){const entry=entries[domain.id];if(!entry)return `<p class="domain-empty">${say('Bu import edilmiş kataloq bölməsində ayrıca control yoxdur.','This imported catalog section has no standalone controls.')}</p>`;
 const lang=state.lang==='az'?0:1,related=state.catalog.sections.find(x=>x.id===entry[2]);
 return `<section class="domain-guidance" data-domain-guidance="${esc(domain.id)}"><span class="domain-guidance-badge">${say('ƏLAVƏ TÖVSİYƏ · CIS CONTROL DEYİL','SUPPLEMENTAL GUIDANCE · NOT A CIS CONTROL')}</span><h3>${esc(domain.title)} · ${say('nələri nəzərdən keçirməli?','what should you review?')}</h3><p>${say('Bu import edilmiş kataloqda həmin GPMC bölməsi üçün ayrıca control yoxdur. Struktur və əlaqəli təhlükəsizlik mövzuları üçün saxlanılıb; bu tövsiyələr 405 control sayına və uyğunluq nəticəsinə daxil edilmir.','This imported catalog has no standalone controls in this GPMC category. It remains for structure and related security topics; these recommendations do not add to the 405 controls or compliance results.')}</p><ul><li>${esc(entry[0][lang])}</li><li>${esc(entry[1][lang])}</li></ul>${related?`<button type="button" data-breadcrumb-domain="${esc(related.id)}">${say('Əlaqəli bölməyə keç','Open related section')}: ${esc(related.title)} →</button>`:''}<a href="https://learn.microsoft.com/en-us/previous-versions/windows/it-pro/windows-10/security/threat-protection/security-policy-settings/security-policy-settings" target="_blank" rel="noopener noreferrer">${say('Microsoft siyasət sənədləri','Microsoft policy documentation')} ↗</a></section>`;
}
window.GpoDomainGuidance=Object.freeze({render});
})();
